#!/usr/bin/env python3
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];O=R/'verification';checks=[]
def ck(n,c,d=None):checks.append({'name':n,'ok':bool(c),'detail':d});print(('OK ' if c else 'FAIL ')+n)
t=json.loads((O/'TERRAIN_CLOUD_V039.json').read_text());s=json.loads((O/'SECURITE_TERRAIN_V039.json').read_text());src=json.loads((O/'SOURCES_OFFICIELLES_V039.json').read_text());m=json.loads((R/'data/map_pack/terrain/manifest_v039.json').read_text())
ck('eight terrain regions',t['complete'] and t['totals']['regions']==8 and len(t['regions'])==8,t['totals']);ck('207 368 samples accounted',t['totals']['valid']+t['totals']['missing']==207368,t['totals']);ck('official RGE ALTI resource',t['source']['resource']=='ign_rge_alti_wld',t['source']);ck('all grids 161 square',all(r['width']==161 and r['height']==161 for r in t['regions']));ck('all terrain hashes present',all(len(r['sha256'])==64 for r in t['regions']));ck('NoData exists only where expected',sum(r['missing'] for r in t['regions'])==32424);ck('no impossible extrema recorded',all(r['min']>-100 and r['max']<9000 and r['min']<=r['max'] for r in t['regions']));ck('manifest agrees with proof',len(m['regions'])==8 and m['source']['resource']==t['source']['resource']);ck('table is client-inaccessible',s['metadataTable']['rls'] and not s['metadataTable']['anonSelect'] and not s['metadataTable']['authenticatedSelect'],s['metadataTable']);ck('terrain bucket private',s['storageBucket']['public'] is False,s['storageBucket']);ck('final service read-only',s['readService']['verifyJwt'] and s['readService']['buildRouteClosed'] and s['readService']['buildRouteStatus']==410,s['readService']);ck('temporary tools disabled',all(v['disabled'] and v['status']==410 for v in s['temporaryTools'].values()),s['temporaryTools']);ck('source proof separates sampling from native resolution','not claimed as native' in src['terrain']['sampling'].lower(),src['terrain']['sampling']);ck('compact ZIP honesty',t['truth']['bundledInCompactZip'] is False,t['truth'])
rep={'version':'0.39.0','passed':sum(x['ok'] for x in checks),'failed':sum(not x['ok'] for x in checks),'total':len(checks),'checks':checks,'scope':'Consistency checks over terrain cloud, security and official-source proof files captured from verified Supabase and Géoplateforme responses.'};(O/'QA_CLOUD_PROOF_V039.json').write_text(json.dumps(rep,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'passed':rep['passed'],'failed':rep['failed'],'total':rep['total']}));raise SystemExit(bool(rep['failed']))
